import formatMoney from './format-money';
import { getLogger } from '~/lib/log';
import { storeKeys } from '../mixins/base-listing-mixin';

getLogger('productRecommendation');

export default function productRecommendation(config = {}) {
  const base = storeKeys(config);
  return {
    ...base,
    products: [],
    currentProductId: config.productId || null,
    ProductRecommendationService: null,
    moneyFormatter: formatMoney,

    async init() {
      const parentProductId = `gid://shopify/Product/${this.currentProductId}`;
      const factory = this.createStorefrontFactory();
      this.ProductRecommendationService = factory.createProductRecommendationService();
      const recommendedProductData = await this.ProductRecommendationService.getRecommendedProducts(parentProductId);
      this.products = recommendedProductData;
    },
  };
}
